import {render} from './art.js';
const q=new URLSearchParams(location.search);let stage=q.get('stage')==='2'?2:12,light=['day','sunset','night'].includes(q.get('light'))?q.get('light'):'day';
const $=id=>document.getElementById(id),labels={day:'Day · 13:00',sunset:'Sunset · 18:30',night:'Night · 22:00'};
function update(){render($('hero'),{stage,light});$('hero').setAttribute('aria-label',`${stage===2?'Early':'Mature'} isometric pixel town, ${labels[light]}`);render($('compare'),{stage});$('compare').setAttribute('aria-label','Pixel-art reinterpretation in daylight');$('original').src=`../../../images/city/level%20${stage}.webp`;$('original').alt=`Existing stage ${stage} town artwork`;$('caption').textContent=`${stage===2?'Early town · home & boat':'Mature town · the full island group'} / ${labels[light]}`;document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===stage)));document.querySelectorAll('[data-light]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.light===light)));history.replaceState(null,'',`?stage=${stage}&light=${light}`);}
document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{stage=+b.dataset.stage;update();});document.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>{light=b.dataset.light;update();});
for(const stage of [2,12])for(const light of ['day','sunset','night']){const f=document.createElement('figure'),c=document.createElement('canvas'),cap=document.createElement('figcaption');render(c,{stage,light});c.role='img';c.setAttribute('aria-label',`Stage ${stage}, ${labels[light]}`);cap.textContent=`${stage===2?'Early':'Mature'} town · ${labels[light]}`;f.append(c,cap);$('gallery').append(f);}
update();document.documentElement.dataset.ready='true';
